import { Tween } from 'cc';
import { GameTask } from './GameTask';
import { SlotMachineState } from '../reel/model/SlotMachineModel';
import type { SlotFreeMultiplierStep, SlotRoundStep } from '../models/SlotRound';
import { runCascadeReels } from './CascadeReelsTask';
import { runCollectWin } from './CollectWinTask';
import type { ISlotGameMain } from '../types/ISlotGameMain';
import type { GameViewAdapter } from '../ui/GameViewAdapter';

/**
 * 免費遊戲單局動畫段：
 * 轉輪/收球邏輯直接呼叫 runCascadeReels()/runCollectWin()（與主流程的
 * CascadeReelsTask/CollectWinTask 共用同一份實作，不重複寫）。
 * rollWinBalance() 仍留在 GameMain_1002（它的 debounce 計時器欄位跨多次呼叫共用同一顆，
 * 屬於 GameMain 狀態，不宜搬進每局都重新建立的 Task 實體）。
 */
export class PlayFreeRoundTask extends GameTask {
    constructor(
        private readonly game: ISlotGameMain<GameViewAdapter>,
        private readonly steps: readonly SlotRoundStep[],
        private readonly freeMul: SlotFreeMultiplierStep | undefined
    ) {
        super();
    }

    protected onStart(): void {
        this.run()
            .catch((error) => console.warn('[PlayFreeRoundTask] failed', error))
            .finally(() => this.finish());
    }

    private async run(): Promise<void> {
        const game = this.game;
        game.slotMachineModel.setState(SlotMachineState.IDLE);
        game.onNormalSpin();
        Tween.stopAllByTarget(game.winBarProxy);
        game.winBarValue = 0;
        game.winBarProxy.v = 0;
        game.setWinBarNum(0);
        await new Promise<void>((r) => setTimeout(r, game.cascadeTiming().fgDelay));
        const fgCols = await runCascadeReels(game, this.steps);
        // 該局贏分：free_multipliers[i].win（已套累積倍率）優先，否則該局各 step win 加總
        const fm = this.freeMul;
        const roundWin = fm?.win !== undefined ? Number(fm.win) || 0 : this.steps.reduce((s, st) => s + (Number(st.win) || 0), 0);
        // 收球：該局有贏分且有倍率球(multiplier>0)時收，accumulated=累積計數器值（API §5.4-4）
        if (fgCols && fm && fm.multiplier > 0 && roundWin > 0) {
            await runCollectWin(game, fgCols, fm.accumulated || 0, true, roundWin);
        }
        game.fgTotalWin += roundWin;
        game.freeSpinsRemaining = Math.max(0, game.freeSpinsRemaining - 1);
        game.updateFgUi();
        if (roundWin > 0) {
            await game.rollWinBalance(game.fgTotalWin, 0.4);
        } else {
            game.storeManager.getModel('TemplateStore').setWinBalance(Number(game.fgTotalWin.toFixed(2)));
        }
    }
}
