import { instantiate, Node, sp, tween, Tween, type TweenEasing, UITransform, Vec3 } from 'cc';
import { GameTask } from './GameTask';
import type { SlotAward, SlotRoundStep } from '../models/SlotRound';
import { WinFloatLabel } from '../reel/view/WinFloatLabel';
import type { ISlotGameMain } from '../types/ISlotGameMain';
import type { GameViewAdapter } from '../ui/GameViewAdapter';

interface IReelSpinStrategy<TGame, TInput> {
    run(game: TGame, input: TInput): Promise<number[][] | null>;
}

/**
 * 轉輪停止 + 消去落下迴圈的完整演出邏輯（原 GameMain_1002.playCascadeReels 及其專屬
 * 子邏輯 runTumbleSwap/applyMultiplierLabelsCol/applyMultiplierLabels/playCharacterMul/
 * playChaMul/spawnWinFloats/playWinFloat/pickCenterCell/shakeScreen，皆已確認只被
 * playCascadeReels 這條路徑呼叫，故整批搬進此檔案，從 GameMain_1002 移除）。
 *
 * 匯出成獨立函式（而非只包在 Task 內）是因為免費遊戲每一局
 * （PlayFreeRoundTask）也需要重跑同一套演出邏輯，兩處共用同一份實作。
 *
 * 2026-08-03：補上 `GameMain_1002.cascadeTiming()`（跟 1001 同步 turbo 三段延遲表，
 * table[0] 即 1002 原本寫死的固定數字：colDelay=80、tumbleClear/tumbleFill=0.45、
 * breath=500ms、explode=0.3、gap=200ms、fill=0.15、fillStagger=0.03），本檔案所有
 * 演出時間值改成讀 `game.cascadeTiming()`，一般速度（table[0]）行為與改動前完全一致，
 * 快速/Turbo 檔位則比照 1001 首次套用分段延遲。
 * Grid normalization 與其他 SG 遊戲一致使用 canonical top-down。
 */
export async function runCascadeReels(game: ISlotGameMain<GameViewAdapter>, steps: readonly SlotRoundStep[]): Promise<number[][] | null> {
    const firstGrid = steps?.[0]?.grid;
    if (!firstGrid?.columns?.length) return null;
    const visibleRows = firstGrid.layout.visibleRows;

    let firstRedShaken = false;

    const shakeScreen = (): void => {
        for (const view of game.allViews) {
            const node = view?.node;
            if (!node || !node.activeInHierarchy) continue;
            const base = node.getPosition();
            Tween.stopAllByTarget(node);
            const t = tween(node);
            const offs = [16, -12, 9, -6, 3];
            for (const dx of offs) t.to(0.045, { position: new Vec3(base.x + dx, base.y - dx * 0.35, base.z) });
            t.to(0.045, { position: new Vec3(base.x, base.y, base.z) }).start();
        }
    };

    /** 單欄套用倍率球 symbol_m 動畫球 + 數字（該欄落定當下就呼叫，避免球先顯示靜態圖一段時間才變） */
    const applyMultiplierLabelsCol = (cols: number[][], sideByCol: number[], col: number): void => {
        const reelsH = game.viewH.slotMachineView.reelViews;
        if (col >= cols.length || col >= reelsH.length) return;
        const side = sideByCol[col] ?? 1;
        for (let row = 0; row < cols[col].length; row++) {
            const m = game.definition.symbols.resolve(cols[col][row]);
            const value = m.kind === 'multiplier' ? m.value : null;
            reelsH[col]?.setMultiplierLabel(row, value, side, m.colorTier);
            game.viewV?.slotMachineView.reelViews[col]?.setMultiplierLabel(row, value, side, m.colorTier);
            if (m.kind === 'multiplier' && m.colorTier === 1 && !firstRedShaken) {
                firstRedShaken = true;
                shakeScreen();
            }
        }
    };

    /** 依盤面 ids 驅動每顆倍率球的 symbol_m 動畫球(side/tier) + 常駐倍率數字，非倍率球清掉 */
    const applyMultiplierLabels = (cols: number[][], sideByCol: number[]): void => {
        const colCount = Math.min(cols.length, game.viewH.slotMachineView.reelViews.length);
        for (let col = 0; col < colCount; col++) applyMultiplierLabelsCol(cols, sideByCol, col);
    };

    const playChaMul = (cha: Node | null): void => {
        const sk = cha?.getComponent(sp.Skeleton);
        if (!sk) return;
        sk.setAnimation(0, 'mul', false);
        sk.setCompleteListener(() => {
            sk.setCompleteListener(null!);
            sk.setAnimation(0, 'idle', true);
        });
    };

    /** 倍率球出現時 cha_001 角色舉手（mul），播完回 idle */
    const playCharacterMul = (active: boolean): void => {
        if (!active) return;
        game.forEachView((v) => {
            playChaMul(v.cha001Skel?.node ?? null);
        });
    };

    const runTumbleSwap = async (boardNamesByCol: string[][], onColFilled?: (col: number) => void): Promise<void> => {
        const timing = game.cascadeTiming();
        const colCount = boardNamesByCol.length;
        const promises: Promise<void>[] = [];
        for (let col = 0; col < colCount; col++) {
            const thisCol = col;
            const symbolNames = boardNamesByCol[col];
            promises.push(
                new Promise<void>((r) => setTimeout(r, col * timing.colDelay))
                    .then(() =>
                        Promise.all(
                            game.allViews.map((v) => {
                                const rv = v.slotMachineView.reelViews[thisCol];
                                return rv ? rv.tumbleClear(timing.tumbleClear, 0.04, timing.tumbleClearEase as TweenEasing) : Promise.resolve();
                            })
                        )
                    )
                    .then(() =>
                        Promise.all(
                            game.allViews.map((v) => {
                                const rv = v.slotMachineView.reelViews[thisCol];
                                return rv ? rv.tumbleFill(symbolNames, timing.tumbleFill, 0.04, undefined, timing.tumbleFillEase as TweenEasing) : Promise.resolve();
                            })
                        )
                    )
                    .then(() => {
                        if (onColFilled) onColFilled(thisCol);
                    })
            );
        }
        await Promise.all(promises);
    };

    const playWinFloat = (parent: Node, pos: Vec3, win: number, _explodeTime: number): void => {
        const node = instantiate(game.winFloatLabel);
        parent.addChild(node);
        node.setPosition(pos);

        const wf = node.getComponent(WinFloatLabel);
        if (wf) {
            wf.play(win);
        } else {
            console.warn('[winFloat] prefab missing WinFloatLabel component');
            node.destroy();
        }
    };

    /** 方形中心最近的 cell（平手取左→上），避開跟 avoid 同列左右相鄰的格子（防數字重疊） */
    const pickCenterCell = (cells: { col: number; row: number }[], avoid: { col: number; row: number }[] = []): { col: number; row: number } => {
        const cols = cells.map((c) => c.col);
        const rows = cells.map((c) => c.row);
        const cx = (Math.min(...cols) + Math.max(...cols)) / 2;
        const cy = (Math.min(...rows) + Math.max(...rows)) / 2;
        const ranked = [...cells].sort((a, b) => {
            const da = (a.col - cx) ** 2 + (a.row - cy) ** 2;
            const db = (b.col - cx) ** 2 + (b.row - cy) ** 2;
            if (Math.abs(da - db) > 1e-6) return da - db;
            if (a.col !== b.col) return a.col - b.col;
            return a.row - b.row;
        });
        const clash = (c: { col: number; row: number }) => avoid.some((p) => p.row === c.row && Math.abs(p.col - c.col) <= 1);
        return ranked.find((c) => !clash(c)) ?? ranked[0];
    };

    /** 中獎群組原地飄分：每種消除 symbol 在其方形中心 cell 飄出該群贏分 */
    const spawnWinFloats = (awards: readonly SlotAward[], colElimRows: Record<number, number[]>, currentCols: number[][], explodeTime: number): void => {
        if (!game.winFloatLabel) return;

        const winBySymbol = new Map<number, number>();
        for (const a of awards) winBySymbol.set(a.symbolId, Number(a.pay) || 0);

        const cellsBySymbol: Record<number, { col: number; row: number }[]> = {};
        for (const colStr of Object.keys(colElimRows)) {
            const col = Number(colStr);
            for (const row of colElimRows[col]) {
                const sym = currentCols[col]?.[row];
                if (sym === undefined) continue;
                (cellsBySymbol[sym] ??= []).push({ col, row });
            }
        }

        const placed: { col: number; row: number }[] = [];
        for (const symStr of Object.keys(cellsBySymbol)) {
            const sym = Number(symStr);
            const win = winBySymbol.get(sym) ?? 0;
            if (win <= 0) continue;
            const center = pickCenterCell(cellsBySymbol[sym], placed);
            placed.push(center);
            const posIdx = center.row + 2;
            for (const v of game.allViews) {
                const rv = v.slotMachineView?.reelViews?.[center.col];
                const parent = v.slotMachineView?.node;
                if (!rv || !parent) continue;
                const worldPos = rv.getCellWorldPosition(posIdx);
                const localPos = parent.getComponent(UITransform)!.convertToNodeSpaceAR(worldPos);
                playWinFloat(parent, localPos, win, explodeTime);
            }
        }
    };

    const timing = game.cascadeTiming(); // 整局固定（spin 當下的檔位）

    const reelViews = game.viewH.slotMachineView.reelViews;
    const colCount = Math.min(firstGrid.columns.length, reelViews.length);

    // side（神）後端沒帶 → 固定為 1（荷魯斯）
    const sideByCol: number[] = [];
    for (let c = 0; c < colCount; c++) sideByCol[c] = 1;

    const frameName = (id: number, col: number): string => {
        return game.definition.symbols.frameName(id, sideByCol[col]);
    };
    const frameIdxByName = (name: string): number => {
        const frames = reelViews[0].spriteFrames;
        for (let i = 0; i < frames.length; i++) if (frames[i]?.name === name) return i;
        return 0;
    };
    // Grid 已經由 SlotRoundMapper／SlotGridDecoder 解碼過（buffer 已移除），這裡只需要複製成可變動的工作副本
    const toMutableCols = (grid: SlotRoundStep['grid']): number[][] => grid.columns.map((column) => [...column.symbolIds]);
    const currentCols = toMutableCols(firstGrid);
    const boardNamesByCol: string[][] = [];
    for (let col = 0; col < colCount; col++) {
        const ids = currentCols[col];
        boardNamesByCol.push(ids.map((id) => frameName(id, col)));
    }

    // 倍率球出現 → 角色舉手(mul)，稍候盤面落定打雷
    const colHasBall = (ids: number[]): boolean => ids.some((id) => game.definition.symbols.resolve(id).kind === 'multiplier');
    const hasAnyBall = currentCols.some((ids) => colHasBall(ids));
    if (hasAnyBall) {
        playCharacterMul(true);
        await new Promise<void>((r) => setTimeout(r, game.charMulLeadMs));
    }

    // 每欄落定當下就套倍率球（不等全部 6 欄），避免球先顯示靜態圖一段時間才切 symbol_m
    await runTumbleSwap(boardNamesByCol, (col) => applyMultiplierLabelsCol(currentCols, sideByCol, col));
    game.allViews.forEach((v) => v.slotMachineModel.onAllStopped());
    applyMultiplierLabels(currentCols, sideByCol);

    // 消除迴圈：跑 server 每個有中獎的 step（終盤段 Awards=null 自動跳過）
    for (let i = 0; i < steps.length; i++) {
        const awards = steps[i].awards.filter((a) => game.definition.symbols.resolve(a.symbolId).kind !== 'scatter');
        if (awards.length === 0) continue;

        await new Promise<void>((r) => setTimeout(r, timing.breath));

        const elimSymbolIds = new Set<number>(awards.map((a) => a.symbolId));
        const nextGrid = steps[i + 1]?.grid;
        const nextCols = nextGrid ? toMutableCols(nextGrid) : null;

        const colElimRows: Record<number, number[]> = {};
        const toMapByCol: Record<number, number[]> = {};
        for (let col = 0; col < colCount; col++) {
            const elimRows: number[] = [];
            for (let row = 0; row < currentCols[col].length; row++) {
                if (elimSymbolIds.has(currentCols[col][row])) elimRows.push(row);
            }
            if (elimRows.length === 0) continue;
            colElimRows[col] = elimRows;
            // 倖存者用「當前盤的 id」保留身分（避免被 nextGrid 覆蓋成別的符號），
            // 新掉落從 nextGrid 該欄頂端取 elimCount 顆（新符號從上面進來）
            const survived = currentCols[col].filter((_, idx) => !elimRows.includes(idx));
            const newFills = nextCols?.[col].slice(0, elimRows.length) ?? [];
            toMapByCol[col] = [...newFills, ...survived].slice(0, visibleRows);
        }

        // 中獎符號爆炸前先播一次 symbol_win
        const winFxPromises: Promise<void>[] = [];
        for (const colStr of Object.keys(colElimRows)) {
            const col = Number(colStr);
            winFxPromises.push(reelViews[col].playWinFx(colElimRows[col], timing.winFx));
            game.viewV?.slotMachineView.reelViews[col]?.playWinFx(colElimRows[col], timing.winFx);
        }
        await Promise.all(winFxPromises);

        // 爆炸 + 群中心飄分
        const explodePromises: Promise<void>[] = [];
        for (const colStr of Object.keys(colElimRows)) {
            const col = Number(colStr);
            explodePromises.push(reelViews[col].explode(colElimRows[col], timing.explode));
            game.viewV?.slotMachineView.reelViews[col]?.explode(colElimRows[col], timing.explode);
        }
        spawnWinFloats(awards, colElimRows, currentCols, timing.float);
        // 用伺服器給的該步驟權威贏分 不要用 awards[].pay 自己加總 兩者可能因倍率等因素對不起來
        const stepWin = Number(steps[i].win) || 0;
        game.addWinBarScore(stepWin);
        await Promise.all(explodePromises);
        await new Promise<void>((r) => setTimeout(r, timing.gap));

        // 掉落
        const fillPromises: Promise<void>[] = [];
        for (const colStr of Object.keys(colElimRows)) {
            const col = Number(colStr);
            const toMapFrames = toMapByCol[col].map((id) => frameIdxByName(frameName(id, col)));
            fillPromises.push(reelViews[col].cascadeFill(toMapFrames, colElimRows[col], timing.fill, timing.fillStagger, undefined, timing.fillEase as TweenEasing));
            game.viewV?.slotMachineView.reelViews[col]?.cascadeFill(toMapFrames, colElimRows[col], timing.fill, timing.fillStagger, undefined, timing.fillEase as TweenEasing);
        }
        await Promise.all(fillPromises);

        for (const colStr of Object.keys(colElimRows)) {
            currentCols[Number(colStr)] = toMapByCol[Number(colStr)];
        }
        applyMultiplierLabels(currentCols, sideByCol); // 先套舊倍率值（升級格此刻顯示舊值）

        // 升級演出（企劃 §20/§17）：整盤只要有消除，所有倖存可升級球都升一階。
        // 落定後對全欄 row-by-row 比對 currentCols(舊) vs nextGrid(新)，變高者播 mul（內部 200ms 切新 tier/值），
        // 並把盤面補成新 id 供下一段 cascade 比對。
        if (nextCols) {
            for (let col = 0; col < colCount; col++) {
                const nextCol = nextCols[col];
                for (let row = 0; row < currentCols[col].length; row++) {
                    const oldM = game.definition.symbols.resolve(currentCols[col][row]);
                    const newM = game.definition.symbols.resolve(nextCol[row]);
                    if (oldM.kind === 'multiplier' && oldM.upgradeable && newM.kind === 'multiplier' && newM.value > oldM.value) {
                        reelViews[col]?.playMultiplierUpgrade(row, sideByCol[col], newM.colorTier, newM.value);
                        game.viewV?.slotMachineView.reelViews[col]?.playMultiplierUpgrade(row, sideByCol[col], newM.colorTier, newM.value);
                        currentCols[col][row] = nextCol[row];
                    }
                }
            }
        }
    }

    // viewV 的 cascade 是 fire-and-forget，把最終盤同步回去
    if (game.viewV) {
        for (let col = 0; col < colCount; col++) {
            const frameIdxes = currentCols[col].map((id) => frameIdxByName(frameName(id, col)));
            game.viewV.slotMachineView.reelViews[col]?.patchVisibleStrip(frameIdxes);
        }
    }

    return currentCols;
}

/**
 * 目前唯一的轉輪消去落下策略：直接委派給 runCascadeReels（tumble/cascade 玩法本體，
 * 含物理式掉落，見 ReelView.physicsFallDuration/appendLandingBounce）。
 * 實作 IReelSpinStrategy 只是把既有邏輯包成可替換的策略物件，行為與搬移前完全一致；
 * 未來新遊戲若要換一套轉輪演出（含一般不消去的 SimpleSpin 玩法），改成 new 一個別的
 * IReelSpinStrategy<ISlotGameMain<GameViewAdapter>> 實作即可，
 * 不需要動 CascadeReelsTask 本身。
 */
export class TumbleCascadeStrategy implements IReelSpinStrategy<ISlotGameMain<GameViewAdapter>, readonly SlotRoundStep[]> {
    public run(game: ISlotGameMain<GameViewAdapter>, steps: readonly SlotRoundStep[]): Promise<number[][] | null> {
        return runCascadeReels(game, steps);
    }
}

/** 對應 SGTask_NGSpin：轉輪停止 + 消去落下迴圈。addTask() 到頂層佇列時用這個薄殼。 */
export class CascadeReelsTask extends GameTask {
    constructor(
        private readonly game: ISlotGameMain<GameViewAdapter>,
        private readonly steps: readonly SlotRoundStep[],
        private readonly onResult: (cols: number[][] | null) => void,
        private readonly strategy: IReelSpinStrategy<ISlotGameMain<GameViewAdapter>, readonly SlotRoundStep[]> = new TumbleCascadeStrategy()
    ) {
        super();
    }

    protected onStart(): void {
        this.strategy
            .run(this.game, this.steps)
            .then((cols) => this.onResult(cols))
            .catch((error) => console.warn('[CascadeReelsTask] failed', error))
            .finally(() => this.finish());
    }
}
